        function Conectar ( $bd = BD_BBDD, $host = BD_HOST, $user = BD_USUARIO, $password = BD_PASS ) {

                $this -> database = $bd;
                $this -> host = $host;
                $this -> user = $user;
                $this -> pass = $password;
                
                
                $this -> conexion = mysqli_connect ( $this -> host , $this -> user , $this -> pass );

                if( !$this -> conexion ) {
                        $this -> Alert("No se ha podido hacer la conexion:".$this -> host."---".$this -> user."---".$this -> pass."----".mysqli_connect_errno()."----".mysqli_connect_error());
                        //$exito = $this -> correo -> NotificarError ("ERROR: No se ha podido conectar a la base de datos '$bd' .", $this->destinoError);
                        exit ();
                }
                
                
                if ( !@mysqli_select_db ( $this -> conexion, $this -> database ) ) {
                    //$exito = $this -> correo -> NotificarError ("ERROR: No se ha podido abrir '$bd' .", $this->destinoError);
                    $this -> Alert("Error al seleccionar la base de datos:".$this -> database.", el error: ".mysqli_errno()."_--".mysqli_error());
                    


                    return 0;

                    }

                //$this->correo = new Mail();



                return true;

                } // Fin constructor Conectar.

        function Desconectar () {

                @mysqli_free_result ($this -> result);
                @mysqli_close ($this -> conexion);

