        function Consultar ( $tabla, $campos = "*", $condicion = "", $orden = "id", $mostrar = false ) {
            
                if ( $condicion )
                                $sql = 'Select '.$campos.' From '.PREFIJO_TABLAS.$tabla.' Where '.$condicion.' Order By '.$orden.'';
                        else
                                $sql = 'Select '.$campos.' From '.PREFIJO_TABLAS.$tabla.' Order By '.$orden.'';

                $this -> sql = $sql; // Copio la cadena sql a la propiedad de la clase para almacenarla

                if ($mostrar)	
                        echo '<div style="border:2px solid #333; background-color:#f0f0f0; padding:7px; margin:7px; font-size:11px; font-family:Arial"><b>SQL</b>: '.$sql.'</div>';

                $this -> result = @mysqli_query ( $this->conexion,$sql );

                if ( $this -> result ) {
                        $this -> row = @mysqli_fetch_array ( $this -> result );
                        $this -> num = @mysqli_num_rows ( $this -> result );
                        return true;
                } else {
                        //$this -> Alert("HA HABIDO UN ERROR EN LA CONSULTA.");
                        //echo "<div style='border:3px solid #f00; background-color:#f0f0f0; padding:7px; margin:7px; font-size:11px; font-family:Arial'>**ERROR[".$this->database."][".$_SERVER['PHP_SELF']."]: Consulta SQL: $sql -- El error: ".mysqli_error($this->conexion)."</div>";
