        /************************************************************************************************************/
        /* Metodo que formatea la fehca                                                                             */
        /************************************************************************************************************/
        function formateaFecha ( $cadena, $hora = false ) { 
                $trozos = explode (" ",$cadena);
                $fecha = explode ("-", $trozos[0]);

                if ($hora) {
                        if ($fecha[2]=='00') return  "No definida";
                        else return $fecha[2]."/".$fecha[1]."/".$fecha[0]." a las ".$trozos [1];
                }else{
                        return $fecha[2]."/".$fecha[1]."/".$fecha[0];
                }
        }

        function Fecha_Calen ( $ini, $fin ) { 
                $fecha_ini_t = explode (" ",$ini);
                $fecha_ini = $fecha_ini_t[0];
                $hora_ini = explode (":", $fecha_ini_t[1]);
                $hora_ini = $hora_ini[0].":".$hora_ini[1];

                $fecha_fin_t = explode (" ",$fin);
                $fecha_fin = $fecha_fin_t[0];
                $hora_fin = explode (":", $fecha_fin_t[1]);
                $hora_fin = $hora_fin[0].":".$hora_fin[1];

                if ($fecha_ini == $fecha_fin) {
                        return $this->formateaFecha($fecha_ini_t[0]). " de ".$hora_ini . " a " .$hora_fin;
                } else {
                        return $this->formateaFecha($fecha_ini_t[0]). " @ ".$hora_ini . " hasta el " .$this->formateaFecha($fecha_fin_t[0]). " @ ".$hora_fin;
                }

        }

