        function DimeMes ($id_mes) {

                switch ($id_mes) {
                        case 1: return "Enero"; break;
                        case 2: return "Febrero"; break;
                        case 3: return "Marzo"; break;
                        case 4: return "Abril"; break;
                        case 5: return "Mayo"; break;
                        case 6: return "Junio"; break;
                        case 7: return "Julio"; break;
                        case 8: return "Agosto"; break;
                        case 9: return "Septiembre"; break;
                        case 10: return "Oct"; break;
                        case 11: return "Noviembre"; break;
                        case 12: return "Diciembre"; break;
                        }

        }

        function SimbolosRaros ($cadena) {

                $cad = strtolower (trim($cadena));

                $cad = eregi_replace (" ", "", $cad);
                $cad = eregi_replace ("�", "a", $cad);
                $cad = eregi_replace ("�", "a", $cad);
                $cad = eregi_replace ("�", "a", $cad);
                $cad = eregi_replace ("�", "e", $cad);
                $cad = eregi_replace ("�", "e", $cad);
                $cad = eregi_replace ("�", "e", $cad);
                $cad = eregi_replace ("�", "i", $cad);
                $cad = eregi_replace ("�", "i", $cad);
                $cad = eregi_replace ("�", "i", $cad);
                $cad = eregi_replace ("�", "o", $cad);
                $cad = eregi_replace ("�", "o", $cad);
                $cad = eregi_replace ("�", "o", $cad);
                $cad = eregi_replace ("�", "u", $cad);
                $cad = eregi_replace ("�", "u", $cad);
                $cad = eregi_replace ("�", "u", $cad);
                $cad = eregi_replace ("�", "n", $cad);
                $cad = eregi_replace ("\"", "", $cad);
                $cad = eregi_replace ("\'", "", $cad);
                $cad = eregi_replace ("\,", "", $cad);
                $cad = eregi_replace ("\.", "", $cad);
                $cad = eregi_replace ("=", "-", $cad);
                $cad = eregi_replace ("�", "", $cad);
                $cad = eregi_replace ("!", "", $cad);
                $cad = eregi_replace (":", "-", $cad);
                $cad = eregi_replace ("%", "", $cad);
                $cad = eregi_replace ("\?", "", $cad);
                $cad = eregi_replace ("\/", "-", $cad);
                $cad = eregi_replace ("\�", "", $cad);
                $cad = eregi_replace ("\(", "", $cad);
                $cad = eregi_replace ("\)", "", $cad);
                $cad = eregi_replace ("&", "", $cad);
                $cad = eregi_replace ("$", "", $cad);
                $cad = eregi_replace ("--", "-", $cad);

                return trim($cad);

        }

        function Nombre_Usuario($cad) {

                $cad = strtolower ($cad);
                $cad = $this->SimbolosRaros ($cad);
                $cad = eregi_replace (" ", "", $cad);
                return strtolower($cad);

        }

        function Metas ($cadena) {
